-- Initial schema. See docs/plan.md §6. Money and sizes are numeric; never floats.
-- IDs are UUIDv7 generated by the server.

-- +goose Up
CREATE TABLE accounts (
    id                 uuid PRIMARY KEY,
    secret_hash        bytea NOT NULL UNIQUE,
    handle             text NOT NULL UNIQUE,
    leaderboard_opt_in boolean NOT NULL DEFAULT true,
    current_run_id     uuid,
    last_reset_at      timestamptz,
    created_at         timestamptz NOT NULL DEFAULT now()
);

-- A run is one $1,000 bankroll. A reset ends the current run and starts a new one.
CREATE TABLE runs (
    id               uuid PRIMARY KEY,
    account_id       uuid NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    starting_balance numeric NOT NULL,
    -- Unrealized PnL at reset, locked into the leaderboard score (plan §5.3).
    locked_upnl      numeric NOT NULL DEFAULT 0,
    started_at       timestamptz NOT NULL DEFAULT now(),
    ended_at         timestamptz
);
CREATE INDEX runs_account_idx ON runs (account_id, started_at);

ALTER TABLE accounts
    ADD CONSTRAINT accounts_current_run_fk
    FOREIGN KEY (current_run_id) REFERENCES runs (id)
    DEFERRABLE INITIALLY DEFERRED;

-- Leverage and margin mode are per account and coin, and exist before any position opens.
CREATE TABLE positions (
    account_id      uuid NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    coin            text NOT NULL,
    run_id          uuid NOT NULL REFERENCES runs (id),
    size            numeric NOT NULL DEFAULT 0, -- signed: positive long, negative short
    entry_px        numeric,
    margin_mode     text NOT NULL DEFAULT 'cross' CHECK (margin_mode IN ('cross', 'isolated')),
    leverage        integer NOT NULL CHECK (leverage >= 1),
    isolated_margin numeric NOT NULL DEFAULT 0,
    updated_at      timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (account_id, coin)
);

CREATE TABLE orders (
    id              uuid PRIMARY KEY,
    account_id      uuid NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    run_id          uuid NOT NULL REFERENCES runs (id),
    coin            text NOT NULL,
    side            text NOT NULL CHECK (side IN ('buy', 'sell')),
    type            text NOT NULL CHECK (type IN (
                        'market', 'limit',
                        'stop_market', 'stop_limit',
                        'take_profit_market', 'take_profit_limit')),
    px              numeric,
    trigger_px      numeric,
    sz              numeric NOT NULL CHECK (sz > 0),
    filled_sz       numeric NOT NULL DEFAULT 0,
    tif             text CHECK (tif IN ('gtc', 'ioc', 'alo')),
    reduce_only     boolean NOT NULL DEFAULT false,
    -- TP/SL attached to an entry order point at it, and share a group so one cancels the other.
    parent_order_id uuid REFERENCES orders (id),
    oco_group       uuid,
    status          text NOT NULL CHECK (status IN (
                        'open', 'triggered', 'filled', 'cancelled', 'rejected')),
    reject_reason   text,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX orders_account_idx ON orders (account_id, created_at DESC);
CREATE INDEX orders_open_idx ON orders (coin) WHERE status IN ('open', 'triggered');

CREATE TABLE fills (
    id             uuid PRIMARY KEY,
    order_id       uuid REFERENCES orders (id), -- null for liquidation closes
    account_id     uuid NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    run_id         uuid NOT NULL REFERENCES runs (id),
    coin           text NOT NULL,
    side           text NOT NULL CHECK (side IN ('buy', 'sell')),
    px             numeric NOT NULL,
    sz             numeric NOT NULL CHECK (sz > 0),
    fee            numeric NOT NULL,
    liquidity      text NOT NULL CHECK (liquidity IN ('maker', 'taker')),
    closed_pnl     numeric NOT NULL DEFAULT 0,
    is_liquidation boolean NOT NULL DEFAULT false,
    created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX fills_account_idx ON fills (account_id, created_at DESC);

-- Append-only. An account's balance is always the sum of its entries for the current run.
CREATE TABLE ledger_entries (
    id         uuid PRIMARY KEY,
    account_id uuid NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    run_id     uuid NOT NULL REFERENCES runs (id),
    kind       text NOT NULL CHECK (kind IN (
                   'deposit', 'fill_pnl', 'fee', 'funding', 'liquidation_fee', 'reset')),
    amount     numeric NOT NULL,
    ref_id     uuid, -- the fill, funding payment or run this entry came from
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ledger_account_run_idx ON ledger_entries (account_id, run_id, created_at);

CREATE TABLE funding_payments (
    id           uuid PRIMARY KEY,
    account_id   uuid NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    run_id       uuid NOT NULL REFERENCES runs (id),
    coin         text NOT NULL,
    funding_hour timestamptz NOT NULL,
    size         numeric NOT NULL,
    rate         numeric NOT NULL,
    oracle_px    numeric NOT NULL,
    amount       numeric NOT NULL,
    -- One payment per position per hour, so restarts can't charge twice (plan §4.7).
    UNIQUE (account_id, coin, funding_hour)
);

CREATE TABLE equity_snapshots (
    account_id     uuid NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    run_id         uuid NOT NULL REFERENCES runs (id),
    ts             timestamptz NOT NULL,
    equity         numeric NOT NULL,
    cumulative_pnl numeric NOT NULL, -- leaderboard score at ts (plan §5.4)
    PRIMARY KEY (account_id, ts)
);
CREATE INDEX equity_snapshots_ts_idx ON equity_snapshots (ts);

-- +goose Down
DROP TABLE equity_snapshots;
DROP TABLE funding_payments;
DROP TABLE ledger_entries;
DROP TABLE fills;
DROP TABLE orders;
DROP TABLE positions;
ALTER TABLE accounts DROP CONSTRAINT accounts_current_run_fk;
DROP TABLE runs;
DROP TABLE accounts;
